let d = msg.payload;
let id = d.id || 1;
let pos = Number(d.pos) || 100;
let carga = (d.carga !== undefined) ? Number(d.carga) : 0;
let color = (carga >= 80 || d.solicita_descarga === 1) ? 'red' : 'green';

let latBase = 40.4168;
let lonBase = -3.7038;
let lat = d.lat || (latBase + (pos * 0.00003));
let lon = d.lon || (lonBase + (pos * 0.00004));

let msgMapa = {
    payload: {
        name: "Cosechadora " + id,
        lat: lat,
        lon: lon,
        icon: "circle",
        iconColor: color,
        layer: "Cosechadoras",
        tooltip: "Cosechadora " + id + " | Tolva: " + carga + "% | Pos: " + pos
    }
};

let msgCard = {
    payload: {
        id: id,
        carga: carga,
        pos: pos,
        alerta: (color === 'red')
    }
};

return [msgMapa, msgCard];
